// ============================================================
// MARKET VISUAL
// ============================================================

const candleData = [
  35, 65, 45, 80, 55, 90, 40, 75, 50, 85, 60, 95,
];

function MarketVisual({
  accentColor,
  reducedMotion,
}: {
  accentColor: string;
  reducedMotion: boolean;
}) {
  return (
    <div
      className="
        absolute inset-0 overflow-hidden
        pointer-events-none rounded-[inherit]
      "
      aria-hidden="true"
    >
      {/* Market candle visualization */}
      <div className="
        absolute inset-0 flex items-end
        justify-between gap-1 px-5 pb-2
        opacity-[0.12] transition-opacity
        duration-500 group-hover:opacity-[0.25]
      ">
        {candleData.map((height, index) => (
          <motion.span
            key={index}
            className="relative w-[3px] shrink-0 rounded-t-full"
            style={{
              backgroundColor:
                index % 2 === 0 ? "#10B981" : "#EF4444",
            }}
            initial={false}
            animate={
              reducedMotion
                ? { height: `${height * 0.55}%` }
                : {
                    height: [
                      `${height * 0.25}%`,
                      `${height * 0.8}%`,
                      `${height * 0.4}%`,
                    ],
                  }
            }
            transition={
              reducedMotion
                ? { duration: 0 }
                : {
                    duration: 2 + (index % 4) * 0.35,
                    repeat: Infinity,
                    repeatType: "reverse",
                    ease: "easeInOut",
                    delay: index * 0.08,
                  }
            }
          />
        ))}
      </div>

      {/* Market waveform */}
      <svg
        viewBox="0 0 500 100"
        preserveAspectRatio="none"
        className="
          absolute inset-0 w-full h-full
          opacity-[0.12] group-hover:opacity-[0.3]
          transition-opacity duration-500
        "
      >
        <defs>
          <linearGradient
            id="owlfx-market-gradient"
            x1="0"
            y1="0"
            x2="1"
            y2="0"
          >
            <stop offset="0%" stopColor="transparent" />
            <stop offset="50%" stopColor={accentColor} />
            <stop offset="100%" stopColor="transparent" />
          </linearGradient>
        </defs>

        <motion.path
          d="
            M0 65
            Q35 20 70 48
            T140 55
            T210 25
            T280 65
            T350 35
            T420 45
            T500 20
          "
          fill="none"
          stroke="url(#owlfx-market-gradient)"
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray="8 5"
          animate={
            reducedMotion
              ? { opacity: 0.8 }
              : { strokeDashoffset: [0, -52] }
          }
          transition={{
            duration: 5,
            repeat: Infinity,
            ease: "linear",
          }}
        />
      </svg>

      {/* Dark contrast overlay */}
      <div className="
        absolute inset-0
        bg-gradient-to-r
        from-[#080D15]/90
        via-[#080D15]/65
        to-[#080D15]/90
      " />
    </div>
  );
}

